          rdg: env.rdg && reported(env.rdg, key, p.name, (t) => rdgNorm(t.tsType)),
        })
      }
    },
    /** One score per tool. Caliper is scored over the universe as well as over the props both list (`counts`, the
     * verdicts of src/oracle.ts): the two must agree, or the universe is not the one the verdicts were made over. */
    score(counts: Record<Verdict, number>): Record<string, ToolScore & { failed_files?: number }> {
      const caliper = scoreTool(entries, (u) => (u as Entry).caliper)
      for (const verdict of VERDICTS) {
        if (caliper.verdicts[verdict] !== counts[verdict]) {
          console.error(`warning: Caliper "${verdict}" is ${counts[verdict]} over the shared props, not ${caliper.verdicts[verdict]} over the universe`)
        }
      }
      return {
        caliper,
        ...(env.rdt && { rdt: scoreTool(entries, (u) => (u as Entry).rdt!) }),
        ...(env.rdg && {
          react_docgen: { ...scoreTool(entries, (u) => (u as Entry).rdg!), failed_files: env.rdg.failed.size },
        }),
      }
    },
  }
}

